import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    y = [0] * n
    for i in range(n):
        x, v = data[1 + 2*i], data[2 + 2*i]
        y[x-1] = v-1
    incomparable = []
    for i in range(n):
        m = 0
        yi = y[i]
        for j in range(n):
            if (i-j) * (yi-y[j]) < 0:
                m |= 1 << j
        incomparable.append(m)
    full = (1 << n) - 1
    seen = {full}
    queue = [full]
    head = 0
    while head < len(queue):
        state = queue[head]
        head += 1
        for k in range(n):
            bit = 1 << k
            if state & bit:
                nxt = (state & incomparable[k]) | bit
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append(nxt)
    print(len(seen) % 998244353)

if __name__ == '__main__':
    main()

