import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    a = [x - 1 for x in data[2:]]

    children = [[] for _ in range(n)]
    indeg = [0] * n
    for i, p in enumerate(a):
        children[p].append(i)
        indeg[p] += 1

    queue = [i for i in range(n) if indeg[i] == 0]
    order = []
    for v in queue:
        order.append(v)
        p = a[v]
        indeg[p] -= 1
        if indeg[p] == 0:
            queue.append(p)

    is_cycle = [x > 0 for x in indeg]
    g = [None] * n
    base = [0] + list(range(1, m + 1))

    # Process non-cycle vertices from leaves toward their cycle.
    for v in order:
        prod = [1] * (m + 1)
        for c in children[v]:
            gc = g[c]
            for k in range(1, m + 1):
                prod[k] = prod[k] * gc[k] % MOD
        cur = 0
        arr = [0] * (m + 1)
        for k in range(1, m + 1):
            cur = (cur + prod[k]) % MOD
            arr[k] = cur
        g[v] = arr

    # h[v][k] is the contribution of the trees attached to cycle vertex v.
    h = [None] * n
    for v in range(n):
        if is_cycle[v]:
            prod = [1] * (m + 1)
            for c in children[v]:
                if not is_cycle[c]:
                    gc = g[c]
                    for k in range(1, m + 1):
                        prod[k] = prod[k] * gc[k] % MOD
            h[v] = prod

    answer = 1
    seen = [False] * n
    for start in range(n):
        if is_cycle[start] and not seen[start]:
            prod = [1] * (m + 1)
            v = start
            while True:
                seen[v] = True
                hv = h[v]
                for k in range(1, m + 1):
                    prod[k] = prod[k] * hv[k] % MOD
                v = a[v]
                if v == start:
                    break
            answer = answer * (sum(prod[1:]) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

