import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    primes = set()
    for x in a:
        y = x
        d = 2
        while d * d <= y:
            if y % d == 0:
                primes.add(d)
                while y % d == 0:
                    y //= d
            d += 1
        if y > 1:
            primes.add(y)

    answer = 1
    for p in primes:
        exponents = []
        total = 0
        for x in a:
            y = x
            e = 0
            while y % p == 0:
                y //= p
                e += 1
            exponents.append(e)
            total += e

        dp = [0] * (total + 1)
        dp[0] = 1

        for length, e in enumerate(exponents, 1):
            nxt = [0] * (total + 1)
            if e == 0:
                for h, value in enumerate(dp):
                    if value:
                        nxt[h] = value * pow(p, h, MOD) % MOD
            else:
                limit = max(total, length * e)
                powers = [1] * (limit + 1)
                for k in range(1, limit + 1):
                    powers[k] = powers[k - 1] * p % MOD
                for h, value in enumerate(dp):
                    if not value:
                        continue
                    # The new height is h+e (the upward choice).
                    nxt[h + e] = (nxt[h + e] + value * powers[h + e]) % MOD
                    if h >= e:
                        z = h - e
                        nxt[z] = (nxt[z] + value * powers[z]) % MOD
                    else:
                        # The path makes a new minimum; all previous
                        # heights are shifted by e-h.
                        shift = length * (e - h)
                        nxt[0] = (nxt[0] + value * powers[shift]) % MOD
            dp = nxt

        answer = answer * (sum(dp) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

