import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:1 + n]
    limit = max(values)

    # Smallest prime factor sieve.
    spf = list(range(limit + 1))
    if limit >= 1:
        spf[1] = 1
    p = 2
    while p * p <= limit:
        if spf[p] == p:
            for multiple in range(p * p, limit + 1, p):
                if spf[multiple] == multiple:
                    spf[multiple] = p
        p += 1

    result = 0
    for value in values:
        omega = 0  # number of prime factors, counted with multiplicity
        while value > 1:
            value //= spf[value]
            omega += 1
        result ^= omega

    sys.stdout.write("Anna\n" if result else "Bruno\n")


