    for i in range(n):
        for j, c in enumerate(g[i]):
            if c != '-':
                k = ord(c) - 97
                outgoing[i][k].append(j)
                incoming[j][k].append(i)

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    heap = []
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))
    for i in range(n):
        for j, c in enumerate(g[i]):
            if c != '-':
                dist[i][j] = 1
                heapq.heappush(heap, (1, i, j))

    while heap:
        w, u, v = heapq.heappop(heap)
        if dist[u][v] != w:
