from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odd_count = (n + 1) // 2
        even_count = n // 2

        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = factorial[i - 1] * i

        total = factorial[odd_count] * factorial[even_count]
        if n % 2 == 0:
            total *= 2
        if k > total:
            return []

        available = list(range(1, n + 1))
        remaining_odd = odd_count
        remaining_even = even_count
        answer = []

        for position in range(n):
            if position == 0:
                allowed = (1,) if n % 2 else (0, 1)
            else:
                allowed = (1 - (answer[-1] % 2),)

            for value in available:
                if value % 2 not in allowed:
                    continue
                next_odd = remaining_odd - (value % 2 == 1)
                next_even = remaining_even - (value % 2 == 0)
                block_size = factorial[next_odd] * factorial[next_even]

                if k > block_size:
                    k -= block_size
                else:
                    answer.append(value)
                    available.remove(value)
                    remaining_odd = next_odd
                    remaining_even = next_even
                    break

        return answer

