class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
        if n % 2:
            total = fact[odds] * fact[evens]
        else:
            total = 2 * fact[odds] * fact[evens]
        if k > total:
            return []
        available = list(range(1, n + 1))
        # For odd n the first element must be odd; for even n either start works.
        start_parity = None
        result = []
        rem_o, rem_e = odds, evens
        for pos in range(n):
            if pos == 0:
                allowed = (1,) if n % 2 else (0, 1)
