                no = rem_o - (x % 2 == 1)
                ne = rem_e - (x % 2 == 0)
                ways = fact[no] * fact[ne]
                if k > ways:
                    k -= ways
                else:
                    result.append(x)
                    available.remove(x)
                    rem_o, rem_e = no, ne
                    break
        return result

