        ifac = [1] * (N - 1)
        ifac[N - 2] = pow(fac[N - 2], MOD - 2, MOD)
        for i in range(N - 2, 0, -1):
            ifac[i - 1] = ifac[i] * i % MOD
        ways = fac[N - 2] * ifac[k - 2] % MOD * ifac[N - k] % MOD

        # Sum of differences over all unordered pairs of positions in a line.
        def pair_sum(length):
            return length * (length - 1) * (length + 1) // 6

        cell_pair_distance_sum = (
            n * n * pair_sum(m) + m * m * pair_sum(n)
        )
        return ways * cell_pair_distance_sum % MOD

