class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        # p[j] is 10^j modulo k.
        p = [1] * n
        for j in range(1, n):
            p[j] = (p[j - 1] * 10) % k

        half = (n + 1) // 2
        coeff = []
        for i in range(half):
            c = p[n - 1 - i]
            if i != n - 1 - i:
                c += p[i]
            coeff.append(c % k)

        # suffix[i] is a bit mask of remainders obtainable by positions i..end.
        suffix = [0] * (half + 1)
        suffix[half] = 1                 # remainder zero
        for i in range(half - 1, -1, -1):
            c = coeff[i]
            old = suffix[i + 1]
            mask = 0
            for d in range(10):
                shift = (d * c) % k
                for r in range(k):
                    if old & (1 << r):
                        mask |= 1 << ((r + shift) % k)
            suffix[i] = mask

        chosen = []
        remainder = 0
        for i, c in enumerate(coeff):
            first = (i == 0)
            for d in range(9, 0 if first else -1, -1):
                needed = (-remainder - d * c) % k
                if suffix[i + 1] & (1 << needed):
                    chosen.append(str(d))
                    remainder = (remainder + d * c) % k
                    break

        left = ''.join(chosen)
        if n & 1:
            return left + left[-2::-1]
        return left + left[::-1]

