from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0]
        for x in nums:
            pref.append(pref[-1] + x)

        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        log = n.bit_length()
        up = [nxt]
        weights = [[nums[i] * (nxt[i] - i) - (pref[nxt[i]] - pref[i])
                    for i in range(n)]]
        for _ in range(1, log):
            old_up, old_w = up[-1], weights[-1]
            new_up = [n] * n
            new_w = [0] * n
            for i in range(n):
                mid = old_up[i]
                if mid < n:
                    new_up[i] = old_up[mid]
                    new_w[i] = old_w[i] + old_w[mid]
                else:
                    new_w[i] = old_w[i]
            up.append(new_up)
            weights.append(new_w)

        def cost(left, right):
            cur = left
            result = 0
            for p in range(log - 1, -1, -1):
                nxt_cur = up[p][cur]
                if nxt_cur <= right:
                    result += weights[p][cur]
                    cur = nxt_cur
            result += nums[cur] * (right - cur + 1) - (pref[right + 1] - pref[cur])
            return result

        answer = 0
        for left in range(n):
            lo, hi = left, n
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(left, mid) <= k:
                    lo = mid + 1
                else:
                    hi = mid
            answer += lo - left
        return answer

