        pos += 2
        counts[(a, b)] = counts.get((a, b), 0) + 1

    # In an optimal composition, functions are ordered from inner to outer
    # by decreasing B/(A-1); A=1 is treated as having infinite ratio.
    types = sorted(
        counts,
        key=lambda t: Fraction(t[1], t[0] - 1)
