    for a, b in types:
        for _ in range(counts[(a, b)]):
            for used in range(k, 0, -1):
                if dp[used - 1] >= 0:
                    candidate = a * dp[used - 1] + b
                    if candidate > dp[used]:
                        dp[used] = candidate
    print(dp[k])


