class DSU:
    def __init__(self, n):
        self.p = list(range(n))
        self.sz = [1] * n
        self.x = [0] * n

    def find(self, a):
        if self.p[a] == a:
            return a, 0
        r, v = self.find(self.p[a])
        self.x[a] ^= v
        self.p[a] = r
        return r, self.x[a]

    def union(self, a, b, w):
        ra, xa = self.find(a)
        rb, xb = self.find(b)
        if ra == rb:
            return (xa ^ xb) == w
        if self.sz[ra] < self.sz[rb]:
            ra, rb = rb, ra
            xa, xb = xb, xa
        self.p[rb] = ra
        self.x[rb] = xa ^ xb ^ w
        self.sz[ra] += self.sz[rb]
        return True

def solve(h, w, s):
    if any(sum(c == 'A' for c in row) & 1 for row in s):
        return 0
    if any(sum(s[i][j] == 'A' for i in range(h)) & 1 for j in range(w)):
