from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return range(n + 1)
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        oa = occurrences(a)
        ob = occurrences(b)
        oc = occurrences(c)
        la, lb, lc = len(a), len(b), len(c)
        answer = n + 1

        for start in oa:
            ib = bisect_left(ob, start + la)
            if ib == len(ob):
                continue
            middle = ob[ib]
            ic = bisect_left(oc, middle + lb)
            if ic == len(oc):
                continue
            finish_c = oc[ic]
            answer = min(answer, finish_c + lc - start)

        return -1 if answer == n + 1 else answer

