import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    potential = [0] * n
    seen = [False] * n
    answer = [0] * n

    for start in range(n):
        if seen[start]:
            continue
        seen[start] = True
        stack = [start]
        component = []
        consistent = True

        while stack:
            v = stack.pop()
            component.append(v)
            for w, z in adj[v]:
                required = potential[v] ^ z
                if not seen[w]:
                    seen[w] = True
                    potential[w] = required
                    stack.append(w)
                elif potential[w] != required:
                    consistent = False

        if not consistent:
            print(-1)
            return

        ones = [0] * 30
        for v in component:
            value = potential[v]
            for bit in range(30):
                ones[bit] += (value >> bit) & 1

        shift = 0
        size = len(component)
        for bit in range(30):
            if ones[bit] > size - ones[bit]:
                shift |= 1 << bit
        for v in component:
            answer[v] = potential[v] ^ shift

    print(*answer)

if __name__ == "__main__":
    main()

