import sys
from itertools import combinations


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    a = data[2:]

    # Enumerate the smaller side.  If we enumerate the complement, its XOR
    # determines the selected set's XOR after XORing with the total XOR.
    use_complement = k > n - k
    r = n - k if use_complement else k

    total = 0
    if use_complement:
        for x in a:
            total ^= x

    best = 0
    for chosen in combinations(a, r):
        value = 0
        for x in chosen:
            value ^= x
        if use_complement:
            value ^= total
        if value > best:
            best = value

    print(best)


if __name__ == "__main__":
    main()

