        w, v = data[2 + 2*i], data[3 + 2*i]
        nd = [NEG] * (W + 1)
        for r in range(min(w, W + 1)):
            hull = deque()
            for t in range((W - r) // w + 1):
                pos = r + t * w
                if dp[pos] > NEG // 2:
                    m = 2 * t
                    b = dp[pos] - t * t - t * v
                    while len(hull) >= 2:
                        m1, b1 = hull[-2]
                        m2, b2 = hull[-1]
                        if (b1 - b2) * (m - m2) >= (b2 - b) * (m2 - m1):
