MOD=998244353

def main():
    data=sys.stdin.read().split()
    if not data:return
    n=int(data[0]); s=data[1]
    # dp indexed by number of currently unmatched vertices
    dp={0:1}
    d=0
    for i,ch in enumerate(s):
        nd={}
        last=(i==len(s)-1)
        for t,val in dp.items():
            # imbalance B-W in prefix before this vertex
            b=(t+d)//2
            w=(t-d)//2
            if ch=='B':
                # leave this B unmatched for a future W
                if not last:
                    nt=t+1; nd[nt]=(nd.get(nt,0)+val)%MOD
                # match it to an unmatched earlier W
                if w:
                    nt=t-1
                    if not last or nt==0:
                        nd[nt]=(nd.get(nt,0)+val*w)%MOD
            else:
                # leave W unmatched for a future B
                if not last:
                    nt=t+1; nd[nt]=(nd.get(nt,0)+val)%MOD
                # match to an earlier unmatched B
                if b:
                    nt=t-1
                    if not last or nt==0:
                        nd[nt]=(nd.get(nt,0)+val*b)%MOD
            d += (1 if ch=='B' else -1)
        dp=nd
        if i<len(s)-1:
            # every cut must have an unmatched B on its left
            dp={t:v for t,v in dp.items() if (t+d)>0}
    print(dp.get(0,0)%MOD)
