    for _ in range(m):
        u, v = a[k]-1, a[k+1]-1
        k += 2
        g[u].append(v); g[v].append(u)

    def bfs(x):
        d = [-1]*n; cnt = [0]*n
        d[x] = 0; cnt[x] = 1
        q = deque([x])
        while q:
            v = q.popleft()
            for w in g[v]:
                if d[w] < 0:
                    d[w] = d[v]+1; cnt[w] = cnt[v]; q.append(w)
                elif d[w] == d[v]+1:
                    cnt[w] = min(2, cnt[w]+cnt[v])
        return d, cnt

