from math import gcd

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)
        pg = [0] * (n + 1)
        pl = [1] * (n + 1)
        for i, x in enumerate(nums):
            pg[i + 1] = gcd(pg[i], x)
            pl[i + 1] = pl[i] // gcd(pl[i], x) * x
        sg = [0] * (n + 1)
        sl = [1] * (n + 1)
        for i in range(n - 1, -1, -1):
            sg[i] = gcd(nums[i], sg[i + 1])
            sl[i] = sl[i + 1] // gcd(sl[i + 1], nums[i]) * nums[i]
        def combine_gcd(a, b):
            return gcd(a, b)
        def combine_lcm(a, b):
            return a // gcd(a, b) * b
        ans = pg[n] * pl[n]
        for i in range(n):
            g = combine_gcd(pg[i], sg[i + 1])
            l = combine_lcm(pl[i], sl[i + 1])
            ans = max(ans, g * l)
        return ans

