import math


def main():
    n = int(sys.stdin.buffer.readline())
    limit = math.isqrt(n)

    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, math.isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b'\x00' * (((limit - start) // p) + 1)

    primes = [p for p in range(2, limit + 1) if sieve[p]]

    # For two distinct primes p,q, (p^2 q^2) has exactly 9 divisors.
    bound = limit
    right = len(primes) - 1
    answer = 0
    for left, p in enumerate(primes):
        while right > left and p * primes[right] > bound:
            right -= 1
        if right <= left:
            break
        answer += right - left

    # p^8 has exactly 9 divisors.
    for p in primes:
        if p ** 8 <= n:
            answer += 1
        else:
            break

    print(answer)


