class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        q = len(queries)

        if all(x == 0 for x in nums):
            return 0

        def feasible(k: int) -> bool:
            # Each position can independently choose a subset of the
            # applicable query values, so solve a subset-sum for each one.
            for i, target in enumerate(nums):
                reachable = 1  # bit s means sum s is reachable
                for l, r, value in queries[:k]:
                    if l <= i <= r:
                        reachable |= reachable << value
                if ((reachable >> target) & 1) == 0:
                    return False
            return True

        if not feasible(q):
            return -1

        lo, hi = 0, q
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

