import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))

        # A prime starting or ending value is forbidden.
        if n == m:
            return -1 if self._is_prime(n) else n
        if self._is_prime(n) or self._is_prime(m):
            return -1

        limit = 10 ** digits
        prime = [True] * limit
        prime[0] = False
        if limit > 1:
            prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                prime[p * p:limit:p] = [False] * (((limit - 1 - p * p) // p) + 1)

        place = [10 ** (digits - 1 - i) for i in range(digits)]
        best = {n: n}  # The initial value is part of the cost.
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != best.get(value):
                continue
            if value == m:
                return cost

            for pos, power in enumerate(place):
                digit = (value // power) % 10
                for new_digit in (digit - 1, digit + 1):
                    if not 0 <= new_digit <= 9:
                        continue
                    # Keep the fixed number of digits; a leading zero is not
                    # a digit of an integer of the given length.
                    if pos == 0 and new_digit == 0:
                        continue
                    nxt = value + (new_digit - digit) * power
                    if prime[nxt]:
                        continue
                    new_cost = cost + nxt
                    if new_cost < best.get(nxt, float('inf')):
                        best[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))

        return -1

    @staticmethod
    def _is_prime(x: int) -> bool:
        if x < 2:
            return False
        d = 2
        while d * d <= x:
            if x % d == 0:
                return False
            d += 1
        return True

