from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # Z[i] is the LCP length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        # Process starting points of the second subarray backwards.
        # nxt[j] is LCP(nums[i+1:], nums[j:]) from the preceding row.
        nxt = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            cur = [0] * (n + 1)
            for j in range(i + 1, n):
                first_works = (j >= 2 * i and z[i] >= i)
                if nums[i] == nums[j]:
                    common = 1 + nxt[j + 1]
                    cur[j] = common
                    if first_works or common >= j - i:
                        answer += 1
                elif first_works:
                    answer += 1
            nxt = cur
        return answer

