class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        is_target = [False] * n
        for i in targetIndices:
            is_target[i] = True

        inf = n + 1
        # dp[j] is the minimum number of target positions used by an
        # embedding of pattern[:j] in the source processed so far.
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            cost = 1 if is_target[i] else 0
            for j in range(m - 1, -1, -1):
                if ch == pattern[j] and dp[j] != inf:
                    candidate = dp[j] + cost
                    if candidate < dp[j + 1]:
                        dp[j + 1] = candidate

        # Every target position not used by this embedding can be removed.
        return len(targetIndices) - dp[m]

