class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # To make every node reach 0, traverse incoming edges backwards from 0.
        rev = [[] for _ in range(n)]
        weights = []
        for a, b, w in edges:
            rev[b].append((a, w))
            weights.append(w)

        values = sorted(set(weights))

        def possible(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in rev[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        count += 1
                        stack.append(u)
            return count == n

        if not values or not possible(values[-1]):
            return -1

        left, right = 0, len(values) - 1
        while left < right:
            mid = (left + right) // 2
            if possible(values[mid]):
                right = mid
            else:
                left = mid + 1
        return values[left]

